12	func (d *DB) CreateIdentityProvider(ctx context.Context, create *store.IdentityProvider) (*store.IdentityProvider, error) {
13		placeholders := []string{"?", "?", "?", "?", "?"}
14		fields := []string{"`uid`", "`name`", "`type`", "`identifier_filter`", "`config`"}
15		args := []any{create.UID, create.Name, create.Type.String(), create.IdentifierFilter, create.Config}
16	
17		stmt := "INSERT INTO `idp` (" + strings.Join(fields, ", ") + ") VALUES (" + strings.Join(placeholders, ", ") + ") RETURNING `id`"
18		if err := d.db.QueryRowContext(ctx, stmt, args...).Scan(&create.ID); err != nil {
19			return nil, err
20		}
21	
22		identityProvider := create
23		return identityProvider, nil
24	}
25	
26	func (d *DB) ListIdentityProviders(ctx context.Context, find *store.FindIdentityProvider) ([]*store.IdentityProvider, error) {
27		where, args := []string{"1 = 1"}, []any{}
28		if v := find.ID; v != nil {
29			where, args = append(where, fmt.Sprintf("id = $%d", len(args)+1)), append(args, *v)
30		}
31		if v := find.UID; v != nil {
32			where, args = append(where, fmt.Sprintf("uid = $%d", len(args)+1)), append(args, *v)
33		}
34	
35		rows, err := d.db.QueryContext(ctx, `
36			SELECT
37				id,
38				uid,
39				name,
40				type,
41				identifier_filter,
42				config
43			FROM idp
44			WHERE `+strings.Join(where, " AND ")+` ORDER BY id ASC`,
45			args...,
46		)
47		if err != nil {
48			return nil, err
49		}
50		defer rows.Close()
51	
52		var identityProviders []*store.IdentityProvider
53		for rows.Next() {
54			var identityProvider store.IdentityProvider
55			var typeString string
56			if err := rows.Scan(
57				&identityProvider.ID,
58				&identityProvider.UID,
59				&identityProvider.Name,
60				&typeString,
61				&identityProvider.IdentifierFilter,
62				&identityProvider.Config,
63			); err != nil {
64				return nil, err
65			}
66			identityProvider.Type = storepb.IdentityProvider_Type(storepb.IdentityProvider_Type_value[typeString])
67			identityProviders = append(identityProviders, &identityProvider)
68		}
69	
70		if err := rows.Err(); err != nil {
71			return nil, err
72		}
73	
74		return identityProviders, nil
75	}
76	
77	func (d *DB) UpdateIdentityProvider(ctx context.Context, update *store.UpdateIdentityProvider) (*store.IdentityProvider, error) {
78		set, args := []string{}, []any{}
79		if v := update.Name; v != nil {
80			set, args = append(set, "name = ?"), append(args, *v)
81		}
82		if v := update.IdentifierFilter; v != nil {
83			set, args = append(set, "identifier_filter = ?"), append(args, *v)
84		}
85		if v := update.Config; v != nil {
86			set, args = append(set, "config = ?"), append(args, *v)
87		}
88		args = append(args, update.ID)
89	
90		stmt := `
91			UPDATE idp
92			SET ` + strings.Join(set, ", ") + `
93			WHERE id = ?
94			RETURNING id, uid, name, type, identifier_filter, config
95		`
96		var identityProvider store.IdentityProvider
97		var typeString string
98		if err := d.db.QueryRowContext(ctx, stmt, args...).Scan(
99			&identityProvider.ID,
100			&identityProvider.UID,
101			&identityProvider.Name,
102			&typeString,
103			&identityProvider.IdentifierFilter,
104			&identityProvider.Config,
105		); err != nil {
106			return nil, err
107		}
108		identityProvider.Type = storepb.IdentityProvider_Type(storepb.IdentityProvider_Type_value[typeString])
109		return &identityProvider, nil
110	}
