112	func (d *DB) DeleteIdentityProvider(ctx context.Context, delete *store.DeleteIdentityProvider) error {
113		where, args := []string{"id = ?"}, []any{delete.ID}
114		stmt := `DELETE FROM idp WHERE ` + strings.Join(where, " AND ")
115		result, err := d.db.ExecContext(ctx, stmt, args...)
116		if err != nil {
117			return err
118		}
119		if _, err = result.RowsAffected(); err != nil {
120			return err
121		}
